<div><article class="panel box"><h2 class="section-title">Score breakdown</h2><div class="break"><?php foreach($result['score']['breakdown'] as $key=>$value):$max=$result['score']['maximum'][$key];?><div><small><?=htmlspecialchars(ucwords(str_replace('_',' ',$key)))?> · <?=$value?>/<?=$max?></small><div class="bar"><i style="width:<?=round($value/$max*100)?>%"></i></div></div><?php endforeach?></div></article><article class="panel box" style="margin-top:10px"><h2 class="section-title">Review flags</h2><?php foreach($result['flags'] as $flag):?><p class="bad"><i class="fa-solid fa-flag"></i> <?=htmlspecialchars($flag)?></p><?php endforeach?><?php if(!$result['flags']):?><p class="good">No rule-based flags.</p><?php endif?><?php foreach($timeline['gaps']??[] as $gap):?><p class="bad"><?=$gap['months']?> month gap · <?=htmlspecialchars($gap['after'].' to '.$gap['before'])?></p><?php endforeach?></article><article class="panel box" style="margin-top:10px"><h2 class="section-title">Detected skills</h2><div class="pills"><?php foreach($result['skills'] as $skill):?><span class="tag"><?=htmlspecialchars($skill)?></span><?php endforeach?></div></article></div></section>
<article class="panel box requirement-panel" data-lab-view="evidence" style="margin-top:10px"><h2 class="section-title">Requirement evidence</h2><?php foreach($result['matches'] as $m):?><div class="match"><strong><?=htmlspecialchars($m['requirement'])?></strong><span class="<?=$m['status']==='missing'?'bad':'good'?>"><?=htmlspecialchars(str_replace('_',' ',$m['status']))?></span><span><?=htmlspecialchars(implode(', ',$m['evidence'])?:'No evidence')?><?=$m['experience_evidence']?' · experience-backed':''?><?=$m['months']?' · '.round($m['months']/12,1).'y':''?></span><b><?=round($m['confidence']*100)?>%</b></div><?php endforeach?><?php if(!$result['matches']):?><div class="empty">This job has no configured required skills.</div><?php endif?></article>
<article class="panel box debug" data-lab-view="resume"><h2 class="section-title">Debug / audit evidence</h2><details><summary>Structured result JSON</summary><pre><?=htmlspecialchars(json_encode(['candidate'=>$person,'contact'=>$contact,'sections'=>array_keys($result['sections']),'skills'=>$result['skills'],'timeline'=>$timeline,'overlaps'=>$result['overlaps'],'matches'=>$result['matches'],'score'=>$result['score'],'flags'=>$result['flags'],'parser'=>array_diff_key($result['parser'],['raw_text'=>1,'normalized_text'=>1]),'ai_status'=>$result['ai_status']],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES))?></pre></details><details><summary>All detected sections</summary><pre><?=htmlspecialchars(json_encode($result['sections'],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES))?></pre></details><details><summary>Normalized text</summary><pre><?=htmlspecialchars($result['parser']['normalized_text'])?></pre></details><details><summary>Raw extracted text</summary><pre><?=htmlspecialchars($result['parser']['raw_text'])?></pre></details></article>
</div><?php endif?><script>document.querySelectorAll('.lab-view-tab').forEach(button=>button.onclick=()=>{document.querySelectorAll('.lab-view-tab').forEach(x=>x.classList.remove('active'));button.classList.add('active');document.querySelectorAll('[data-lab-view]').forEach(view=>view.classList.toggle('active',view.dataset.labView===button.dataset.viewTarget))});document.querySelectorAll('.tab-button').forEach(button=>button.onclick=()=>{document.querySelectorAll('.tab-button,.tab-panel').forEach(x=>x.classList.remove('active'));button.classList.add('active');document.getElementById('tab-'+button.dataset.tab).classList.add('active')});const favorite=document.getElementById('labFavorite');if(favorite){const key='evidence-favorite:'+favorite.dataset.key;const render=()=>{const active=localStorage.getItem(key)==='1';favorite.classList.toggle('active',active);favorite.innerHTML='<i class="fa-'+(active?'solid':'regular')+' fa-star"></i> '+(active?'Favorited':'Favorite')};favorite.onclick=()=>{localStorage.setItem(key,localStorage.getItem(key)==='1'?'0':'1');render()};render()}</script><?php require __DIR__.'/views/partials/footer.php';?>
